using System.Collections.Generic;
using NewFeature.Models;

namespace NewFeature.Services.Repositories
{
    // Generated from the official Vehicle Management submission
    // "Fleet Details Till 20th Aug - 20-08-2026.xlsx" (received 21-08-2026, 702 vehicles).
    //
    // Column mapping / editorial decisions:
    //   Bus NO.            -> BusNumber            (source's own unique fleet id; the real business key)
    //   ID NO.              -> LicensePlate          (government plate/ID; 100 rented buses have none in
    //                                                 the source, so they get a "RENTED-<BusNumber>"
    //                                                 placeholder here, which is guaranteed unique since
    //                                                 BusNumber is unique - this keeps LicensePlate's
    //                                                 existing Required+Unique contract unchanged)
    //   Name                -> Make (parsed) + Model  (Make is extracted by keyword match - Yutong,
    //                                                 Zhongtong/Zhontong, King Long, Coaster, Asia Star,
    //                                                 or "Rented Fleet" for the Al Barkha rentals; Model
    //                                                 keeps the full source name text)
    //   Model (source col)  -> Year                   (this source column is actually the model year)
    //   Operation           -> Status                 (Yes -> Active, No -> Available; the source has no
    //                                                 richer status such as InMaintenance/OutOfService)
    //   Shasia NO.          -> ChassisNumber           (VIN; null for the 100 rows missing registration
    //                                                 papers, same rows as the missing plate)
    //   Bus Type            -> BusTypeCode             (internal type code, e.g. "CityYT2020")
    //   Air COND.           -> HasAirConditioning
    //   MAxkilo             -> MaxKilometers           (distinct from Mileage - this is a max/limit field
    //                                                 from the register, not a live odometer reading;
    //                                                 the source has no odometer column at all, so
    //                                                 Mileage is left null for every seeded row)
    //   Responsibility      -> IsInStorage / ResponsibilityCode
    //                                                 ("Storage" -> IsInStorage = true; an "R######"
    //                                                 code -> ResponsibilityCode, meaning the vehicle is
    //                                                 currently checked out under that responsibility)
    //   employeeNameBorrower -> ResponsibleEmployeeName (who currently has custody, when checked out)
    //
    // Columns intentionally NOT carried over (low/no signal across all 702 rows, see the Phase 3
    // report): COMP. Serial, Search name, Sort field 2 (1 non-blank value), Licnse NO. (always
    // blank), PASS. NO. (18 rows, single repeated value), Colors Code (always blank), OPER. Card
    // (702/702 "Yes"), Responsibility2 / employeeADDNameBorrower (a secondary/historical assignment
    // pair, 137 rows - can be added back as a real field later if the business needs it).
    //
    // Capacity is left null for every row: the source register does not carry seat counts, and
    // guessing a number per bus type would fabricate data that was never actually collected.
    //
    // Regenerate this file from the source workbook rather than hand-editing it if the register
    // changes; do not hand-edit the literal list below.
